function RW.due(k, gap) local t = os.clock() if t - (RW.at[k] or -1e9) < gap then return false end RW.at[k] = t return true end
function RW.index()
    local d = M.data()
    if d and D.CI and type(D.CI.Sections) == "table" and D.CI.CanClaim then
        for _, s in ipairs(D.CI.Sections) do
            if s.Reward and s.Rarity then
                local ok, can = pcall(D.CI.CanClaim, d, s.Rarity)
                if ok and can and RW.due("ix" .. s.Rarity, 30) then invoke("ClaimIndex", s.Rarity) return end
            end
        end
        return
    end
    if not (d and D.CC and type(D.CC.ByRarity) == "table" and type(D.CC.RarityOrder) == "table") then return end
    local idx, claimed = d.Index or {}, d.IndexClaims or {}
    for _, r in ipairs(D.CC.RarityOrder) do
        local list = D.CC.ByRarity[r]
        if type(list) == "table" and #list > 0 and not claimed[r] then
            local all = true
            for _, c in ipairs(list) do local id = type(c) == "table" and c.Id or c if not idx[id] then all = false break end end
            if all and RW.due("ix" .. r, 30) then invoke("ClaimIndex", r) return end
        end
    end
end
function RW.redeem(list)
    local got = 0
    for _, c in ipairs(list) do
        c = tostring(c):upper():gsub("%s", "")
        local d = M.data()
        if c ~= "" and not (d and type(d.PromoCodes) == "table" and d.PromoCodes[c]) then
            local res = invoke("PromoCode", c)
            if type(res) == "table" and res.Ok then got = got + 1
            elseif type(res) == "table" and (res.Reason == "Wait" or res.Reason == "Busy") then task.wait(3) res = invoke("PromoCode", c) if type(res) == "table" and res.Ok then got = got + 1 end end
            task.wait(3.5)
        end
    end
    return got
end
