function AF.reset()
    if type(getgc) ~= "function" then return end
    local now = os.clock()
    if AF.cells and #AF.cells > 0 then
        for _, c in ipairs(AF.cells) do pcall(debug.setupvalue, c[1], c[2], now) end
        return
    end
    AF.cells = {}
    pcall(function()
        for _, f in ipairs(getgc()) do
            if type(f) == "function" then
                local ok, s = pcall(debug.info, f, "s")
                if ok and type(s) == "string" and s:find("AntiIdleRejoin") then
                    local okU, ups = pcall(debug.getupvalues, f)
                    if okU and type(ups) == "table" then
                        for i, v in pairs(ups) do
                            if type(v) == "number" and not AF.skip[v] and v > now - 1200 and v <= now + 1 then pcall(debug.setupvalue, f, i, now) AF.cells[#AF.cells + 1] = { f, i } end
                        end
                    end
                end
            end
        end
    end)
end
