    local CG = Tab:AddRightGroupbox(__T["Changelog"], "list")
    CG:AddLabel('<font color="#f5c542"><b>2026-11-07  v1.0</b></font>', true)
    local groups = {
        { __T["Farm"], { "+ Auto kill farm", "+ Best zone or pick", "+ Kill speed", "+ Golden event bonus", "+ Auto unlock zones", "+ Auto bosses + filter", "+ God mode", "+ Auto rebirth + stop", "+ Auto bank packs", "+ Grab dropped packs" } },
