        { __T["Shop"], { "+ Auto upgrades", "+ Best aura", "+ Best trail", "+ Auto potions", "+ Bench upgrade", "+ Auto lift", "+ Daily / offline", "+ Index rewards", "+ Free forever pack", "+ Auto codes" } },
        { "Player", { "+ Speed + jump", "+ Anti AFK", "+ Teleports", "+ World travel", "+ Carrier ESP", "+ Server hop" } },
        { "Other", { "+ Streamer mode", "+ Executor check" } },
    }
    for _, g in ipairs(groups) do
        CG:AddLabel('<b>' .. g[1] .. '</b>', true)
