    table.sort(worlds)
    Tq:AddDropdown("tp_world", { Text = __T["World"], Values = worlds, Default = worlds[1] })
    Tq:AddButton({ Text = __T["Travel"], Func = function()
        local n = tonumber(tostring(val("tp_world", "World 1")):match("%d+")) or 1
