    SV:AddButton({ Text = __T["Server Hop"], Func = function()
        local ok, body = pcall(function() return game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&limit=100") end)
        if ok then
